    self.EventMonthCardRefresh = Events.AddListener(Constants.EventNames.OnMonthCardRefresh, Bind(self, self.OnMonthCardRefresh))

    SetButtonAction(self.BtnDrink, Bind(self, self.OnBtnDrink))
    SetButtonAction(self.BtnFood, Bind(self, self.OnBtnFood))
    SetButtonAction(self.BtnOrder, Bind(self, self.OnBtnBuy))
    --SetButtonAction(self.BtnLeft, Bind(self, self.OnBtnLeft))
    --SetButtonAction(self.BtnRight, Bind(self, self.OnBtnRight))
    SetButtonAction(self.BtnTips, Bind(self, self.OnBtnArrow))
    SetButtonAction(self.BtnAdd, function()
        local StoreUtils = import('Game.UI.Store.StoreUtils')
        StoreUtils.OpenMonthCard(Constants.MonthCardDialogOpenType.InvestigateTeam, {{id = Constants.UITypeIds.UIMainInteractionOrderDialog}})
    end)

    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end    
    self._curSelectRoleId = checkNumber(argument.staticRoleId)

    self._specialRoleId = checkNumber(argument.specialRoleId)
    KTool.SetActive(self.DialogueFrameNode, self._specialRoleId > 0)
    --self._isHasMonthCard = checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.CoffeeNum)) > 0
    self._isHasMonthCard = false
    self._roleInstance = RolesShowMgr:GetInstance():GetRoleInstance(StaticRoleId)

    self:InitData()

    if self._specialRoleId > 0 then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1810, "RoleShowVo", self._specialRoleId)
        if vo then
            CfUtils.FillText(self.TxtLeftName, vo.name)
        end
    end
    --self:RefreshOrderNumInfo()

    KTool.SetActive(self.DialogueFrameNode, true)


    --self:RefreshPagePoints()
    self:RefreshFoodSelect()
end

