--初始化数据
function UIMainInteractionOrderDialog:InitData()
    if not self._allRoleData then
        local allRoleData = PhoneUtils.GetAllUnlockCatIdArray()
        table.sort(allRoleData, function(a, b)
            if PhoneUtils.GetRoleOrderNum(b) > 0 and PhoneUtils.GetRoleOrderNum(a) > 0 then
                local blevel = PhoneUtils.GetCatFavorabilityLevel(b) 
                local alevel = PhoneUtils.GetCatFavorabilityLevel(a) 
                if blevel == alevel then
                    return checkNumber(a) < checkNumber(b)
                else
                    return alevel > blevel
                end
            elseif PhoneUtils.GetRoleOrderNum(a) > 0 and PhoneUtils.GetRoleOrderNum(b) <= 0 then
                return true
            end
            return false
        end)

        self._allRoleData = allRoleData
    end
    if not self._allOrderFoodData then
        self._allOrderFoodData = {}
        local t = self:GetAllOrderFoodData()

        local _drinkT = {}
        local _eatT = {}
        for k, v in pairs(t) do
            if checkNumber(v.type) == FoodType.Drink then
                table.insert(_drinkT, v)
            elseif checkNumber(v.type) == FoodType.Eat then
                table.insert(_eatT, v)
            end

            --[[
            if table.count(_drinkT) == PageFoodCount then
                if not self._allOrderFoodData[FoodType.Drink] then
                    self._allOrderFoodData[FoodType.Drink] = {}
                end
                table.insert(self._allOrderFoodData[FoodType.Drink], _drinkT)
                _drinkT = {}
            elseif table.count(_eatT) == PageFoodCount then
                if not self._allOrderFoodData[FoodType.Eat] then
                    self._allOrderFoodData[FoodType.Eat] = {}
                end
                table.insert(self._allOrderFoodData[FoodType.Eat], _eatT)
                _eatT = {}
            end
            ]]
        end
        self._allOrderFoodData[FoodType.Drink] = _drinkT
        self._allOrderFoodData[FoodType.Eat] = _eatT

        --[[
        if table.count(_drinkT) > 0 then
            table.insert(self._allOrderFoodData[FoodType.Drink], _drinkT)
        elseif table.count(_eatT) > 0 then
            table.insert(self._allOrderFoodData[FoodType.Eat], _eatT)
        end
        ]]
    end
end

--左上角信息
function UIMainInteractionOrderDialog:RefreshOrderNumInfo()
    local curOrderNum = phoneComp:GetCurOrderTimes()
    local maxCfOrderNum = PhoneUtils.GetMaxCfOrderTimes()
    local isHaveConsume = false

    --local monthCardNum = checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.CoffeeNum))
    local monthCardNum = 0
    local isBuyMonthCard = (monthCardNum > 0)
    for i = 1, 5 do
        local go = self.Item.transform:Find("go"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.ImgIcon, self.Item)
            go.name = "go"..i
        end
        KTool.SetActive(go, true)

        local satus = 1
        if i <= curOrderNum then
            satus = 3
        --elseif (checkNumber(self._curSelectDrinkId) > 0 or checkNumber(self._curSelectFoodId) > 0) and not isHaveConsume then
        elseif self._curStatus and not isHaveConsume then
            isHaveConsume = true
            satus = 2
        elseif i > maxCfOrderNum then
            satus = 4--isBuyMonthCard and 4 or 5
        end

        if i > maxCfOrderNum then
            KTool.SetActive(go.transform:Find("ImgLock"), not isBuyMonthCard)
        end
        KTool.SetActive(go.transform:Find("ImgSelect"), satus == 2)

        CfUtils.SetUISwitchImage(go.transform:Find("ImgIcon"), satus)
    end
    CfUtils.FillText(self.TxtState, "月卡有效期内,每日可购买套装数量<color=#80ff63>+"..checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.CoffeeNum)).."</color>")
end

