--刷新特效
function UIMainInteractionOrderDialog:RefreshEffectGo(name)
    name = checkString(name)
    local path = "Effect/prefab/coffee/"..name..".prefab"

    if not isNull(self._effectGo) then
        GameObject.Destroy(self._effectGo)
    end
    self._effectGo = nil

    if string.isEmpty(name) then
        return
    end
    local loader = self:GetLoader(path)
    local go = GameObject.Instantiate(loader.ResultObject)
    if not isNull(go) then
        go.transform.parent = self._parGo.transform:Find("RolePar/"..self._curSelectRoleId)
        self._effectGo = go
        self._effectGo.transform.localPosition = Vector3(0, 0, 0)
        self._effectGo.transform.localRotation = Quaternion.Euler(0, 0, 0)
        self._effectGo.transform.localScale = Vector3(1, 1, 1)
    end
end

--台词信息
function UIMainInteractionOrderDialog:RefreshTalkInfo(type)
    self._curStatus = type
    local talkType = self:GetTalkInfo(type)
    local catId = checkNumber(self._specialRoleId) ---当前为小白
    if checkNumber(self._curSelectRoleId) > 0 then
        catId = checkNumber(self._curSelectRoleId) ---当前选中的不是小白
    end
    local PhoneUtils = import('Game.Utils.PhoneUtils')

    local vo = PhoneUtils.GetRoleTalkVo(catId, talkType)
    if not vo then
        return
    end
    CfUtils.FillText(self.TxtContent, CfUtils.GetSexDesc(vo.text, self._curSelectRoleId))


    local go
    if not isNull(self._roleAni) then
        go = self._roleAni.gameObject
    end

    if CfUtils.IsWoman() then
        CriWareUtils.PlayVoiceById(vo.voicecodeLady, go)
    else
        CriWareUtils.PlayVoiceById(vo.voicecode, go)
    end

    if self._roleInstance then
        self._roleInstance:SetCoffeeInteger(checkNumber(vo.action))

        if self._roleTalkCo then
            cs_coroutine.stop(self._roleTalkCo)
            self._roleTalkCo = nil
        end

        self._roleTalkCo = cs_coroutine.start(function()
            self:RefreshEffectGo(vo.specialEffects)
            coroutine.yield(Yielders.GetWaitForSeconds(1))
            self._roleInstance:SetCoffeeInteger(0)
        end)
    end
end

function UIMainInteractionOrderDialog:GetTalkInfo(status)
    local type = TalkType.Id1
    if status == Status.None then
        type = TalkType.Id1
    elseif status == Status.SelectRole then
        if self._curSelectRoleId == self._specialRoleId then
            type = TalkType.Id2
        else
            type = TalkType.Id2
        end
    elseif status == Status.SelectDrink then
        local isLike = PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, self._curSelectDrinkId)
        if self._curSelectRoleId == self._specialRoleId then
            if isLike then
                type = TalkType.Id3
            else
                type = TalkType.Id4
            end
        else
            if isLike then
                type = TalkType.Id3
            else
                type = TalkType.Id4
            end
        end
    elseif status == Status.SelectFood then
        local isLike = PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, self._curSelectFoodId)
        if self._curSelectRoleId == self._specialRoleId then
            if isLike then
                type = TalkType.Id5
            else
                type = TalkType.Id5
            end
        else
            if isLike then
                type = TalkType.Id5
            else
                type = TalkType.Id6
            end
        end
    elseif status == Status.Buy then
        local isCanBuy = PhoneUtils.GetOrderConsumeGoodsNum(self._curSelectFoodId, self._curSelectDrinkId) <= GoodsUtils.GetThingNo(PhoneUtils.GetOrderConsumeGoodsId())
        if not isCanBuy then
            type = TalkType.Id8
        else
            if self._curSelectRoleId == self._specialRoleId then
                type = TalkType.Id7
            else
                type = TalkType.Id7
            end
        end
    elseif status == Status.XiaobaoSelectRole then
        type = TalkType.Id10
    end
    return type
end

function UIMainInteractionOrderDialog:FillSelf()
    local num = 0 --CfUtils.GetWholeVo(AutoIds.IdSetting602, "MonthCardRewardVo")[1].privilege["coffeeNum"]
    if self._isHasMonthCard then
        num = checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.CoffeeNum))
    end
    CfUtils.FillText(self.Text, "月卡有效期内,每日可邀请成员数<color=#88efff>+"..num.."</color>")
    CfUtils.SetUISwitchImage(self.BtnTips, self._isHasMonthCard and 2 or 1)
    local isSelectRole = (checkNumber(self._curSelectRoleId) > 0)
    KTool.SetActive(self.InviteFriends, not isSelectRole)
    KTool.SetActive(self.Menu, isSelectRole)

    if not isSelectRole then
        local num1, num2 = (PhoneUtils.GetMaxOrderTimes() - phoneComp:GetCurOrderTimes()),  PhoneUtils.GetMaxOrderTimes()
        if num1 < 0 then
            num1 = 0
        end
        
        if self._isHasMonthCard then
            CfUtils.FillText(self.TxtTitleRole, localize("今日还可邀请_num1_".."/<color=#ff1daa>_num2_</color>位成员", {_num1_ = num1, _num2_ = num2}))
        else
            CfUtils.FillText(self.TxtTitleRole, localize("今日还可邀请_num1_".."/_num2_位成员", {_num1_ = num1, _num2_ = num2}))
        end
        self:FillInviteInfo()
        self:RefreshTalkInfo(Status.None)

        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1810, "RoleShowVo", self._specialRoleId)
        if vo then
            CfUtils.FillText(self.TxtLeftName, vo.name)
        end
    else
        self:FillMenuInfo()
        self:RefreshTalkInfo(Status.SelectRole)
    end
end

--绘制邀请成员信息
function UIMainInteractionOrderDialog:FillInviteInfo()
    if not self._isInitRoleView then
        self.LoopList:InitListView(#self._allRoleData, Bind(self, self.OnGetRoleCellByIndex))
        self._isInitRoleView = true
    else
        GameUtils.ReloadData(self.LoopList, #self._allRoleData)
    end
end

function UIMainInteractionOrderDialog:OnGetRoleCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._allRoleData[index + 1]
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell, UIMainInteractionOrderRoleNode)
    if scr then
        scr:Refresh(id, index, function()
            if PhoneUtils.GetRoleOrderNum(id) <= 0 then
                GameUtils.Toast(localize("该角色今日邀请次数已用完"))
                return
            elseif phoneComp:GetCurOrderTimes() >= PhoneUtils.GetMaxOrderTimes() then
                GameUtils.Toast(localize("今日邀请次数已用完"))
                return
            end
            self:OnSelectRole(id)
        end)
    end
    return cell
end

function UIMainInteractionOrderDialog:OnSelectRole(catId)
    cs_coroutine.start(function()
        CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIMainInteractionOrderPartTL")
        --self:OnBtnArrow()
        if self._specialRoleId > 0 then
            self:RefreshTalkInfo(Status.XiaobaoSelectRole)
        end
        self._curSelectRoleId = checkNumber(catId)

        local isLoadSuccess = false
        local time = GameUtils.ShowBlackOverlay(nil, function()
            while not isLoadSuccess do
                coroutine.yield(Yielders.EndOfFrame)
            end
        end)
        coroutine.yield(WaitForSeconds(time))

        coroutine.yield(WaitForSeconds((1)))
        coroutine.yield(self:InitRoleModle())

        CfUtils.SetActive(self.Root, false)
        self:FillMenuInfo()
        isLoadSuccess = true

        local camGo = RolesShowMgr:GetInstance():GetInteractiveCam(StaticRoleId)
        if camGo then
            CfUtils.ChangeMainCamDefalultBlend(0)
            KTool.SetActive(camGo, false)
        end

        local camName = "Camera_cofa_"..self._curSelectRoleId
        RolesShowMgr:GetInstance():SetCameraActivity(true, camName, true)
        self:RefreshTalkInfo(Status.SelectRole)


        if not isNull(self._part1Go) then
            local pd = KTool.GetComponent(self._part1Go, typeof(CS.UnityEngine.Playables.PlayableDirector))
            if not isNull(pd) then
                pd:Play()
                coroutine.yield(WaitForSeconds((2.83)))
            end
        else
        end
        CfUtils.SetActive(self.Root, true)
        CfUtils.SetActive(self.DialogueFrameNode, false)
        coroutine.yield(WaitForSeconds((3.6 - 2.83)))
        CfUtils.SetActive(self.DialogueFrameNode, true)

        self:InitPart2Go()
        --self:RefreshOrderNumInfo()
        CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainInteractionOrderPartTL")
    end)
end

