--菜单的view
function UIMainInteractionOrderDialog:RefreshFoodView()
    self._curPageFoodData = self:GetCurPageFoodData()

    if not self._isInitMenuView then
        self.LoopGridView:InitGridView(#self._curPageFoodData, Bind(self, self.OnGetFoodCellByIndex))
        self.LoopGridView.mOnSnapNearestChanged = Bind(self, self.OnSnapNearestChanged)
        self._isInitMenuView = true
    else
        GameUtils.ReloadData(self.LoopGridView, #self._curPageFoodData)
        --self.LoopGridView:SetListItemCount(table.count(self._curPageFoodData))
        self.LoopGridView:MovePanelToItemByIndex(0)
    end
end

function UIMainInteractionOrderDialog:OnSnapNearestChanged(listView, item)
    local ind = self.LoopGridView.CurSnapNearestItemIndex

    self._curPageInd = ind + 1
    --self:RefreshFoodView()
    self:FillTextPage()
    --self:RefreshPagePoints()
    self:RefreshArrow()
end

function UIMainInteractionOrderDialog:OnGetFoodCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._curPageFoodData[index + 1]
    local Cell = self.LoopGridView:NewListViewItem("Cell")

    local scr = CfUtils.GetLuaScr(Cell, UIMainInteractionOrderFoodNode)
    if scr then
        scr:Refresh(data, self._curSelectRoleId, function()
            local go = self.LoopGridView:GetShownItemByItemIndex(self._curSelectFoodInd)
            if go then
                local lastScr = CfUtils.GetLuaScr(go, UIMainInteractionOrderFoodNode)
                if lastScr then
                    lastScr:RefreshSelect(false)
                end
            end

            self._curSelectFoodInd = index
            scr:RefreshSelect(true)
            self:OnSelectFood(data)
        end)

        if checkNumber(self._curSelectFoodId) == checkNumber(data.id) then
            scr:RefreshSelect(true)
        elseif checkNumber(self._curSelectDrinkId) == checkNumber(data.id) then
            scr:RefreshSelect(true)
        end
    end

    return Cell
end

--选择一个食物
function UIMainInteractionOrderDialog:OnSelectFood(vo)
    if not vo then
        return
    end

    local go 
    if checkNumber(vo.type) == FoodType.Drink then
        go = self.BtnDrink
        self._curSelectDrinkId = vo.id
        if self._specialRoleId > 0 then
            self:RefreshTalkInfo(Status.SelectDrink)
        end
        --self:InitFoodModle(true)
    elseif checkNumber(vo.type) == FoodType.Eat then
        go = self.BtnFood
        self._curSelectFoodId = vo.id
        if self._specialRoleId > 0 then
            self:RefreshTalkInfo(Status.SelectFood)
        end
        --self:InitFoodModle(false)
    end
    self:RefreshFoodSelect()
    
    self:FillSelectFoodInfo(go, vo)
    self:RefreshConsumeInfo()
end

--刷新支付信息
function UIMainInteractionOrderDialog:RefreshConsumeInfo()
    local consumeGoodsId = PhoneUtils.GetOrderConsumeGoodsId()
    local path = GoodsConfMgr:GetInstance():GetPhotoPathById(consumeGoodsId)
    CfUtils.FillImage(self.ImgIconGoods, path)

    local consumeNum = 0
    if checkNumber(self._curSelectFoodId) > 0 then
        local vo = CookingUtils.GetOrderFoodVo(self._curSelectFoodId)
        if vo then
            consumeNum = consumeNum + checkNumber(vo.coinNum)
        end
    end
    
    if checkNumber(self._curSelectDrinkId) > 0 then
        local vo = CookingUtils.GetOrderFoodVo(self._curSelectDrinkId)
        if vo then
            consumeNum = consumeNum + checkNumber(vo.coinNum)
        end
    end

    CfUtils.FillText(self.TextNumber3, consumeNum)
    local status1, status2 = 1, 0
    if (checkNumber(self._curSelectFoodId) <= 0) or (checkNumber(self._curSelectDrinkId) <= 0) then
        status1 = 2
        status2 = 3

        CfUtils.SetActive(self.ActiveNode, false)
    else
        status1 = (GoodsUtils.GetThingNo(consumeGoodsId) >= consumeNum and 1 or 2)
        status2 = status1
        CfUtils.SetActive(self.ActiveNode, true)
    end 

    CfUtils.SetUISwitchText(self.TextNumber3, status2)
    CfUtils.SetUISwitchImage(self.BtnOrder.transform:Find("ImgFinger"), status2)
    CfUtils.SetUISwitchImage(self.BtnOrder.transform:Find("ImgBgText"), status1)

end

--绘制选择食物信息
function UIMainInteractionOrderDialog:FillSelectFoodInfo(go, vo)
    local selectedGroupGo = go.transform:Find("SelectedGroup")
    local unselectedGroupGo = go.transform:Find("UnselectedGroup")

    if not vo then
        KTool.SetActive(selectedGroupGo, false)
        KTool.SetActive(unselectedGroupGo, true)
        KTool.SetActive(go.transform:Find("LikeabilityActiveNode"), false)
        KTool.SetActive(go.transform:Find("SpecialFeelingUp"), false)
        return
    end
    KTool.SetActive(selectedGroupGo, true)
    KTool.SetActive(unselectedGroupGo, false)
    KTool.SetActive(go.transform:Find("LikeabilityActiveNode"), true)

    local iconGo = selectedGroupGo.transform:Find("ImgIcon")
    CfUtils.FillImage(iconGo, vo.picture)
    CfUtils.FillText(selectedGroupGo.transform:Find("TextNumber"), PhoneUtils.GetRoleAddNum(self._curSelectRoleId, vo.id)) --vo.love)

    local isLike = PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, vo.id)
    KTool.SetActive(go.transform:Find("LikeabilityActiveNode"), isLike)

    KTool.SetActive(go.transform:Find("SpecialFeelingUp"), isLike)
    if isLike then
        CfUtils.FillText(go.transform:Find("SpecialFeelingUp/AnimRoot/TextNumber2"), checkInt(PhoneUtils.GetOrderFavorabilityAdd() * 100).."%")
    end
end

