--所有的套餐食品
function UIMainInteractionOrderDialog:GetAllOrderFoodData()
    local t = CfUtils.GetCfTable(AutoIds.IdSetting2011)
    if not t then
        return {}
    end
    local _t = {}
    for k, v in pairs(t) do
        local vo = OrderFoodVo.New()
        vo:FillVo(v)
        table.insert(_t, vo)
    end 
    --[[
    table.sort(_t, function(a, b)
        if CookingUtils.IsUnlockFood(b.id) and CookingUtils.IsUnlockFood(a.id) then
            if PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, b.id) and PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, a.id) then
                return checkNumber(a.id) < checkNumber(b.id)
            elseif not PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, b.id) and PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, a.id) then
                return true
            end
        elseif not CookingUtils.IsUnlockFood(b.id) and CookingUtils.IsUnlockFood(a.id) then
            return true
        end
        return false
    end)
    ]]
    for i = 1, #_t do
        for j = i + 1, #_t do
            local vo1 = _t[i]
            local vo2 = _t[j]

            local isChange = false
            if CookingUtils.IsUnlockFood(vo2.id) and not CookingUtils.IsUnlockFood(vo1.id) then
                isChange = true
            elseif CookingUtils.IsUnlockFood(vo1.id) and not CookingUtils.IsUnlockFood(vo2.id) then
                isChange = false
            elseif CookingUtils.IsUnlockFood(vo1.id) and CookingUtils.IsUnlockFood(vo2.id) then
                if PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, vo2.id, true) and not PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, vo1.id, true) then
                    isChange = true
                elseif PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, vo1.id, true) and not PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, vo2.id, true) then
                    isChange = false
                else
                    isChange = (checkNumber(vo2.sort) < checkNumber(vo1.sort))
                end
            else
                isChange = (checkNumber(vo2.sort) < checkNumber(vo1.sort))
            end

            if isChange then
                local data = vo1
                _t[i] = vo2
                _t[j] = data
            end
        end
    end
    return _t
end

function UIMainInteractionOrderDialog:ChangeFoodType(type)
    self._curFoodType = type
    self._curPageInd = 1
    self:RefreshFoodView()
    if self._curFoodType == FoodType.Drink then
        CfUtils.FillText(self.TxtTitle, localize("选择套餐中的饮料"))
    else
        CfUtils.FillText(self.TxtTitle, localize("选择套餐中的食物"))
    end

    self:RefreshFoodSelect()
end

function UIMainInteractionOrderDialog:RefreshFoodSelect() 
    local status = 1
    if checkNumber(self._curSelectDrinkId) ~= 0 then
        status = 3
    else
        local isLike = PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, self._curSelectDrinkId)
        if isLike then
            status = 2
        end
    end
    CfUtils.SetUISwitchImage(self.BtnDrink, status)

    status = 1
    if checkNumber(self._curSelectFoodId) ~= 0 then
        status = 3
    else
        local isLike = PhoneUtils.IsRoleLikeFood(self._curSelectRoleId, self._curSelectFoodId)
        if isLike then
            status = 2
        end
    end
    CfUtils.SetUISwitchImage(self.BtnFood, status)

    KTool.SetActive(self.BtnDrink.transform:Find("ImgSelectGroup"), self._curFoodType == FoodType.Drink)
    KTool.SetActive(self.BtnFood.transform:Find("ImgselectGroup"), self._curFoodType == FoodType.Eat)
end

--左
function UIMainInteractionOrderDialog:OnBtnLeft() 
    if self._curPageInd <= 1 then
        return
    end

    self._curPageInd = self._curPageInd - 1
    self.LoopGridView:MovePanelToItemIndex(self._curPageInd - 1)

    --self:RefreshFoodView()
    self:FillTextPage()
    self:RefreshPagePoints()
    self:RefreshArrow()
end

--右
function UIMainInteractionOrderDialog:OnBtnRight()
    local maxNum = table.count(self._allOrderFoodData[self._curFoodType])
    if self._curPageInd >= maxNum then
        return
    end

    self._curPageInd = self._curPageInd + 1
    self.LoopGridView:MovePanelToItemIndex(self._curPageInd - 1)

    --self:RefreshFoodView()
    self:FillTextPage()
    --self:RefreshPagePoints()
    self:RefreshArrow()
end

function UIMainInteractionOrderDialog:RefreshArrow()
    local lStatus, rStatus = 1, 1
    if self._curPageInd <= 1 then
        lStatus = 2
    end
    local maxNum = table.count(self._allOrderFoodData)
    if self._curPageInd >= maxNum then
        rStatus = 2
    end
    --CfUtils.SetUISwitchImage(self.BtnLeft.transform:Find("Img"), lStatus)
    --CfUtils.SetUISwitchImage(self.BtnRight.transform:Find("Img"), rStatus)

    local lRedPoint = false
    local rRedPoint = false
    local t
    if self._curPageInd > 1 then
        t = self._allOrderFoodData[self._curPageInd - 1]
        lRedPoint = self:IsMapHasNew(t)
    end

    if self._curPageInd < maxNum then
        t = self._allOrderFoodData[self._curPageInd + 1]
        rRedPoint = self:IsMapHasNew(t)
    end
    --KTool.SetActive(self.BtnLeft.transform:Find("CommonRedPoint"), lRedPoint)
    --KTool.SetActive(self.BtnRight.transform:Find("CommonRedPoint"), rRedPoint)
end

--是否有新的数据
function UIMainInteractionOrderDialog:IsMapHasNew(t)
    if not t then
        return false
    end
    for k, v in pairs(t) do
        if CookingUtils.IsNewRecipe(v.menu) then
            return true
        end
    end
    return false
end

function UIMainInteractionOrderDialog:RefreshPagePoints()
    local count = table.count(self._allOrderFoodData)
    for i = 1, count do
        local go = self.Page.transform:Find("point"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.ImgSquare, self.Page)
            go.name = "point"..i
            KTool.SetActive(go, true)
        end
        local status = (checkNumber(self._curPageInd) == i) and 1 or 2
        CfUtils.SetUISwitchImage(go, status)
    end
end

