                end

                if not isNull(self._part1Go) then
                    GameObject.Destroy(self._part1Go)
                    self._part1Go = nil
                end
                                
                if not isNull(self._part2Go) then
                    GameObject.Destroy(self._part2Go)
                    self._part2Go = nil
                end
            else
                local camName = "Camera_cofa_"..self._curSelectRoleId
                RolesShowMgr:GetInstance():SetCameraActivity(false, camName, true)
                UIModule.BackDialog()
            end
        end)

        local camGo = RolesShowMgr:GetInstance():GetInteractiveCam(checkString(self._specialRoleId))
        if not isNull(camGo) then
            self._fPos = camGo.transform.position
            local tPos = Vector3(0, 0, -0.2)
