function UIMainInteractionOrderDialog:GetLoader(path)
    path = checkString(path)
    --创建
    if isNull(RolesShowMgr:GetInstance():GetCoffeeLoader(path)) then
        local roleLoader = ResourceModule.LoadBundleAsync(path, nil, true)
        while not roleLoader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end
        if roleLoader.IsSuccess then
            self:PushLoader(roleLoader, path) 
        else
            roleLoader:Release()
            return nil
        end
        return roleLoader
    end
    return RolesShowMgr:GetInstance():GetCoffeeLoader(path)
end

function UIMainInteractionOrderDialog:PushLoader(loader, path)
    RolesShowMgr:GetInstance():PushCoffeeLoader(loader, path)
end

--获取模型
function UIMainInteractionOrderDialog:GetModelGo(path, par)
    if isNull(par) then
        return
    end

    path = checkString(path)
    --创建
    if isNull(RolesShowMgr:GetInstance():GetCoffeeGo(path)) then
        local loader = self:GetLoader(path, nil, true)
        if not isNull(loader) then
            local go = KTool.Instantiate(par.gameObject, loader.ResultObject, true)
            RolesShowMgr:GetInstance():PushCoffeeGo(go, path)
        end
    end
    return RolesShowMgr:GetInstance():GetCoffeeGo(path)
end

--获取模型
function UIMainInteractionOrderDialog:GetRoleModelGo(roleId, par)
    if isNull(par) then
        return
    end

    roleId = checkString(roleId)
    --创建
    if isNull(RolesShowMgr:GetInstance():GetCoffeeGo(roleId)) then
        local loader = RolesShowMgr:GetInstance():GetRoleLoaderByRoleId(roleId)
        if not isNull(loader) then
            local go = CfUtils.InstantiateGo(loader.ResultObject.gameObject, par)
            RolesShowMgr:GetInstance():PushCoffeeGo(go, roleId)
        end
    end
    return RolesShowMgr:GetInstance():GetCoffeeGo(roleId)
end

--角色模型
function UIMainInteractionOrderDialog:InitRoleModle()
    self:ClearControllerGo()

    local go = self:GetRoleModelGo(self._curSelectRoleId, self._parGo.transform:Find("RolePar/"..self._curSelectRoleId))
    KTool.SetActive(go, true)
    if isNull(go) then
        return
    end
    self._camCldrc.enabled = false

    local vo = PhoneUtils.GetPhoneRoleVisitingVo(self._curSelectRoleId)
    local path = ""
    if vo then
        path = vo.animator
    end
    local loader = self:GetLoader(path)

    self._controllerGo = GameObject.Instantiate(loader.ResultObject)

    self._roleAni = KTool.GetOrAddComponent(go, typeof(Animator))
    self._roleAni.runtimeAnimatorController = self._controllerGo

    self._roleAni:SetInteger("idle", 6)

    --机器人出来
    loader = self:GetLoader("Timeline/EnterPrefab/Coffee/menu_part01_timeline.prefab")
    self._part1Go = GameObject.Instantiate(loader.ResultObject)
    if not isNull(self._part1Go) then
        self._part1Go.transform.parent = self._parGo.transform

        local pd = KTool.GetComponent(self._part1Go, typeof(CS.UnityEngine.Playables.PlayableDirector))
        if isNull(pd) then
            return
        end
        pd.time = 0
        pd:Pause()
    end

    self._camCldrc.enabled = true
end

function UIMainInteractionOrderDialog:InitPart2Go()
    local loader = self:GetLoader("Timeline/EnterPrefab/Coffee/menu_part02_timeline.prefab")
    self._part2Go = GameObject.Instantiate(loader.ResultObject)
    if not isNull(self._part2Go) then
        self._part2Go.transform.parent = self._parGo.transform
    end

    if not isNull(self._part1Go) then
        GameObject.Destroy(self._part1Go)
        self._part1Go = nil
    end
end

--清空状态机的实例
function UIMainInteractionOrderDialog:ClearControllerGo()
    if not isNull(self._controllerGo) then
        GameObject.Destroy(self._controllerGo)
    end
end

--绘制喝咖啡场景的模型
function UIMainInteractionOrderDialog:InitFoodModle(isDrink)
    if isDrink then
        if not isNull(self._drinkGo) then
            KTool.SetActive(self._drinkGo, false)
        end
        local vo = CookingUtils.GetOrderFoodVo(self._curSelectDrinkId)
        if vo and not string.isEmpty(vo.model) then
            self._drinkGo = self:GetModelGo(vo.model, self._parGo.transform:Find("DrinkPar"))
            if not isNull(self._drinkGo) then
                KTool.SetActive(self._drinkGo, true)
            end
            self._drinkGo.transform.localPosition = Vector3(0, 0, 0)
        end
    else
        if not isNull(self._foodGo) then
            KTool.SetActive(self._foodGo, false)
        end
        vo = CookingUtils.GetOrderFoodVo(self._curSelectFoodId)
        if vo and not string.isEmpty(vo.model) then
            self._foodGo = self:GetModelGo(vo.model, self._parGo.transform:Find("FoodPar"))
            if not isNull(self._foodGo) then
                KTool.SetActive(self._foodGo, true)
            end
            self._foodGo.transform.localPosition = Vector3(0, 0, 0)
        end
    end
end


function UIMainInteractionOrderDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        RolesShowMgr:GetInstance():ClearCoffeeLoaderAndGo()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        local go = GameObject.Find("Camera")
        if not isNull(go) then
            self._camCldrc = KTool.GetComponent(go.gameObject, typeof(CS.CustomLightDirRelativeCamera))
        end

        CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIMainInteractionOrderPartTL")

        self._staticRoleId = checkNumber(argument.staticRoleId)
        local camGo
        --不是小白进来的
        if self._staticRoleId > 0 and self._staticRoleId ~= StaticRoleId then
            --Events.Broadcast(Constants.EventNames.MainHomeRoleActive, {isShow = true})
            --Events.Broadcast(Constants.EventNames.MainHomeRoleActive, {isShow = false, roleId = StaticRoleId})

            Events.Broadcast(Constants.EventNames.MainHomeRoleActive, {isShow =  false})

            local isLoadSuccess = false
            local time = GameUtils.ShowBlackOverlay(nil, function()
                while not isLoadSuccess do
                    coroutine.yield(Yielders.EndOfFrame)
                end
            end)
            coroutine.yield(WaitForSeconds(time))

            coroutine.yield(self:InitRoleModle())
            isLoadSuccess = true

            local vo = CfUtils.GetCfVo(AutoIds.IdSetting1810, "RoleShowVo", self._staticRoleId)
            camGo = RolesShowMgr:GetInstance():GetInteractiveCam(vo.roleCamera)
            if camGo then
                KTool.SetActive(camGo, false)
            end

            local camName = "Camera_cofa_"..self._curSelectRoleId
            RolesShowMgr:GetInstance():SetCameraActivity(true, camName, true)
        else
            Events.Broadcast(Constants.EventNames.MainHomeRoleActive, {isShow = true, roleId = StaticRoleId})

            local camGo = RolesShowMgr:GetInstance():GetInteractiveCam(StaticRoleId)
            if camGo then
                CfUtils.ChangeMainCamDefalultBlend(0)
                KTool.SetActive(camGo, true)
            end
        end
        Events.Broadcast(Constants.EventNames.MainHomeRoleActivity, { isActivity = false})

        CfUtils.RefreshTopGoods({Constants.Currency.GoldId})
        
        local path = GoodsConfMgr:GetInstance():GetPhotoPathById(PhoneUtils.GetOrderConsumeGoodsId())
        CfUtils.FillImage(self.ImgIconGoods, path)

        if self._roleInstance then
            self._roleInstance:InitCooffeeController()
        end

        --不是小白进来的
        if self._staticRoleId > 0 and self._staticRoleId ~= StaticRoleId then
            CfUtils.SetActive(self.Root, false)
            self:FillSelf()
            self._partCo = cs_coroutine.start(function()
                if not isNull(self._part1Go) then
                    local pd = KTool.GetComponent(self._part1Go, typeof(CS.UnityEngine.Playables.PlayableDirector))
                    if not isNull(pd) then
                        pd:Play()
                        coroutine.yield(WaitForSeconds(2.83))
                    end
                end
                CfUtils.SetActive(self.Root, true)

                self:InitPart2Go()
                CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainInteractionOrderPartTL")
            end)
        else
            self:FillSelf()
            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainInteractionOrderPartTL")
        end

    end))
    return coWait
end

function UIMainInteractionOrderDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._effectGo) then
            GameObject.Destroy(self._effectGo)
        end

        if self._partCo then
            cs_coroutine.stop(self._partCo)
            self._partCo = nil
        end
        CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIMainInteractionOrderPartTL")

        if not isNull(self._part1Go) then
            GameObject.Destroy(self._part1Go)
        end
        if not isNull(self._part2Go) then
            GameObject.Destroy(self._part2Go)
        end

        if self._co then
            cs_coroutine.stop(self._co)
            self._co = nil
        end

        if self._roleTalkCo then
            cs_coroutine.stop(self._roleTalkCo)
            self._roleTalkCo = nil
        end

        if not self._isPlayStory then
            RolesShowMgr:GetInstance():ClearCoffeeLoaderAndGo()
        end
        --self:ClearControllerGo()

        --播放剧情的时候全部隐藏
        if self._isPlayStory then
            Events.Broadcast(Constants.EventNames.MainHomeRoleActive, {isShow = false})
        end

        local camGo = RolesShowMgr:GetInstance():GetInteractiveCam(self._specialRoleId)
        if camGo then
            camGo.transform.position = self._fPos
        end
        Events.RemoveListener(Constants.EventNames.OnMonthCardRefresh, self.EventMonthCardRefresh)
        Events.RemoveListener(Constants.EventNames.OnMonthCardExpired, self.EventMonthCardStop)
        self._roleInstance:RevertStatus()

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIMainInteractionOrderDialog
